class PacedTrainException(BaseModel):
    """
    Represents an exception for a paced train occurrence.
    Occurrences are normally generated from a base paced train.
    An exception occurs when an occurrence is added or modified
    compared to the base model. Each field corresponds to a "ChangeGroup" of attributes
    that may deviate from the paced train.
    - Created: A new occurrence manually added by the user, not originally present in the automatically generated occurrences based on the paced train.
    - Modified: An existing occurrence that has been changed
    """

    occurrence_index: StrictInt | None = None
    constraint_distribution: ConstraintDistributionChangeGroup | None = None
    initial_speed: InitialSpeedChangeGroup | None = None
    labels: LabelsChangeGroup | None = None
    options: OptionsChangeGroup | None = None
    path_and_schedule: PathAndScheduleChangeGroup | None = None
    rolling_stock: RollingStockChangeGroup | None = None
    rolling_stock_category: RollingStockCategoryChangeGroup | None = None
    speed_limit_tag: SpeedLimitTagChangeGroup | None = None
    start_time: StartTimeChangeGroup | None = None
    train_name: TrainNameChangeGroup | None = None
    disabled: StrictBool | None = None
    id: StrictInt | None = None
    """
    TODO The new exception table id (for incremental migration)
    """
    key: StrictStr
    """
    Unique key for the exception within the paced train, required and generated by the frontend.
    """


class Paced(BaseModel):
    exceptions: list[PacedTrainException]
    interval: Annotated[timedelta, Field(examples=["PT2H"])]
    """
    Time between two occurrences, an ISO 8601 format is expected
    """
    time_window: Annotated[timedelta, Field(examples=["PT2H"])]
    """
    Duration of the paced train, an ISO 8601 format is expected
    """


